namespace AccessControl;

public sealed class AccessDecisionEngine
{
    public AccessDecision Decide(Principal? principal, Resource? resource, AccessRequest? request, IDelegationRegister delegations)
    {
        if (TryGetContextFailure(principal, resource, request, out var decision))
            return decision;

        var validatedPrincipal = principal!;
        var validatedResource = resource!;
        var validatedRequest = request!;

        if (TryGetStateFailure(validatedPrincipal, validatedResource, validatedRequest, out decision))
            return decision;

        var administrator = validatedPrincipal.Roles.Contains("administrator");
        var operatorRole = validatedPrincipal.Roles.Contains("operator");
        var auditor = validatedPrincipal.Roles.Contains("auditor");
        var owner = validatedPrincipal.Id == validatedResource.OwnerId;
        var delegated = delegations.HasDelegation(validatedPrincipal.Id, validatedResource.Id, validatedRequest.Action);

        if (TryGetPolicyDecision(validatedResource, validatedRequest, administrator, out decision))
            return decision;
        if (TryGetAuthorizationFailure(validatedRequest.Action, administrator, operatorRole, auditor, owner, delegated, out decision))
            return decision;

        var outsideBusinessHours = validatedRequest.MinuteOfDay < 480 || validatedRequest.MinuteOfDay > 1080;
        return new AccessDecision(true, delegated ? "delegated" : "role-or-ownership", outsideBusinessHours || validatedResource.Classification == "restricted");
    }

    private static bool TryGetContextFailure(
        Principal? principal,
        Resource? resource,
        AccessRequest? request,
        out AccessDecision decision)
    {
        if (principal is null || resource is null || request is null)
        {
            decision = new AccessDecision(false, "missing-context", true);
            return true;
        }

        if (string.IsNullOrWhiteSpace(principal.Id) || string.IsNullOrWhiteSpace(resource.Id))
        {
            decision = new AccessDecision(false, "invalid-identity", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static bool TryGetStateFailure(
        Principal principal,
        Resource resource,
        AccessRequest request,
        out AccessDecision decision)
    {
        if (principal.Suspended)
        {
            decision = new AccessDecision(false, "principal-suspended", true);
            return true;
        }

        if (!string.Equals(principal.TenantId, resource.TenantId, StringComparison.Ordinal))
        {
            decision = new AccessDecision(false, "tenant-mismatch", true);
            return true;
        }

        if (resource.Locked && request.Action != "read")
        {
            decision = new AccessDecision(false, "resource-locked", true);
            return true;
        }

        if (request.MinuteOfDay is < 0 or > 1439)
        {
            decision = new AccessDecision(false, "invalid-time", true);
            return true;
        }

        if (principal.FailedChallenges >= 3 && !request.StrongAuthentication)
        {
            decision = new AccessDecision(false, "challenge-required", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static bool TryGetPolicyDecision(
        Resource resource,
        AccessRequest request,
        bool administrator,
        out AccessDecision decision)
    {
        if (request.BreakGlass)
        {
            decision = !administrator || !request.StrongAuthentication
                ? new AccessDecision(false, "invalid-break-glass", true)
                : new AccessDecision(true, "break-glass", true);
            return true;
        }

        if (resource.Classification == "restricted" && !request.StrongAuthentication)
        {
            decision = new AccessDecision(false, "strong-authentication-required", true);
            return true;
        }

        if (resource.Classification == "restricted" && request.NetworkZone != "trusted")
        {
            decision = new AccessDecision(false, "trusted-network-required", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static bool TryGetAuthorizationFailure(
        string action,
        bool administrator,
        bool operatorRole,
        bool auditor,
        bool owner,
        bool delegated,
        out AccessDecision decision)
    {
        switch (action)
        {
            case "delete":
                if (!administrator)
                {
                    decision = new AccessDecision(false, "administrator-required", true);
                    return true;
                }
                break;

            case "write":
                if (!HasWriteAccess(administrator, operatorRole, owner, delegated))
                {
                    decision = new AccessDecision(false, "write-not-authorised", true);
                    return true;
                }
                break;

            case "read":
                if (!HasReadAccess(administrator, operatorRole, auditor, owner, delegated))
                {
                    decision = new AccessDecision(false, "read-not-authorised", false);
                    return true;
                }
                break;

            default:
                decision = new AccessDecision(false, "unknown-action", true);
                return true;
        }

        decision = default!;
        return false;
    }

    private static bool HasWriteAccess(bool administrator, bool operatorRole, bool owner, bool delegated) =>
        administrator || operatorRole || owner || delegated;

    private static bool HasReadAccess(bool administrator, bool operatorRole, bool auditor, bool owner, bool delegated) =>
        administrator || operatorRole || auditor || owner || delegated;
}
